import React, { useState, useEffect } from 'react';
import Papa from 'papaparse'; // Ensure this is installed: npm install papaparse
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================

// 1. BACKEND CONNECTION
// Ensure this matches your Django server URL
const BACKEND_URL = 'http://127.0.0.1:8000'; 
const PRESIGN_ENDPOINT = '/api/s3-presign'; 

// 2. FILE NAMES (Must match your S3 bucket exactly)
// Note: If your file in S3 is named "forecast_output (1).csv", rename it to "forecast_output.csv" for simplicity
const CSV_FILE_NAME = 'forecast_output.csv'; 
const TXT_FILE_NAME = 'lime_sentences_manual.txt';

const RiverDashboard = () => {
    // State for data
    const [chartData, setChartData] = useState([]);
    const [limeSentences, setLimeSentences] = useState([]);
    
    // State for UI
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [lastUpdated, setLastUpdated] = useState(null);

    // ==========================================
    // DATA FETCHING LOGIC
    // ==========================================

    // Helper: Get secure AWS URL from Django
    const getPresignedUrl = async (fileName) => {
        try {
            const response = await fetch(`${BACKEND_URL}${PRESIGN_ENDPOINT}?file=${fileName}`);
            if (!response.ok) throw new Error(`Backend Error: ${response.statusText}`);
            const data = await response.json();
            return data.url; 
        } catch (err) {
            console.error(`Failed to sign URL for ${fileName}:`, err);
            return null;
        }
    };

    const fetchData = async () => {
        setLoading(true);
        setError(null);

        try {
            // 1. Get Signed URLs from Backend
            const csvUrl = await getPresignedUrl(CSV_FILE_NAME);
            const txtUrl = await getPresignedUrl(TXT_FILE_NAME);

            if (!csvUrl || !txtUrl) throw new Error("Could not connect to AWS backend.");

            // 2. Add Timestamp to bust browser cache (Force new download)
            const timestamp = new Date().getTime();
            const bustCache = (url) => `${url}&t=${timestamp}`;

            // 3. Fetch & Parse CSV (Forecast Data)
            const csvResponse = await fetch(bustCache(csvUrl));
            const csvText = await csvResponse.text();

            Papa.parse(csvText, {
                header: true,
                skipEmptyLines: true,
                complete: (results) => {
                    // Map CSV columns to your chart data format
                    const parsedData = results.data.map(row => ({
                        // Ensure these match your CSV headers exactly!
                        time: row.Timestamp, 
                        level: parseFloat(row.Predicted_Water_Level)
                    }));
                    setChartData(parsedData);
                },
                error: (err) => { throw new Error(`CSV Parse Failed: ${err.message}`); }
            });

            // 4. Fetch & Parse TXT (LIME Explanations)
            const txtResponse = await fetch(bustCache(txtUrl));
            const txtData = await txtResponse.text();
            
            // Clean text data
            const lines = txtData.split('\n')
                .filter(line => line.trim() !== '')
                .slice(0, 10); // Optional: Limit to top 10 lines
                
            setLimeSentences(lines);

            // 5. Update UI
            setLastUpdated(new Date().toLocaleTimeString());
            setLoading(false);

        } catch (err) {
            console.error("Error fetching live data:", err);
            setError("Unable to load live data.");
            setLoading(false);
        }
    };

    // Initial Load + Auto-Refresh every 10 mins
    useEffect(() => {
        fetchData();
        const interval = setInterval(fetchData, 600000); 
        return () => clearInterval(interval);
    }, []);

    // ==========================================
    // RENDER (Your Exact Design)
    // ==========================================
    return (
        <div className="dashboard-container">
            <h1 className="dashboard-title">River Water Level Forecast</h1>
            
            {/* Status Bar */}
            <div style={{ textAlign: 'center', marginBottom: '20px', color: '#666', fontSize: '0.9rem' }}>
                {loading && <span>⏳ Syncing with AWS Cloud...</span>}
                {error && <span style={{color: 'red'}}>⚠️ {error}</span>}
                {!loading && !error && <span>✅ Live Data (Updated: {lastUpdated})</span>}
            </div>

            <div className="dashboard-content">
                
                {/* 1. CHART CARD */}
                <div className="chart-card">
                    <h2>Water Level Trends</h2>
                    
                    {chartData.length > 0 ? (
                        <div style={{ padding: '20px' }}>
                            {/* --- REPLACE THIS SECTION WITH YOUR CHART COMPONENT --- */}
                            {/* Example: <LineChart data={chartData} ... /> */}
                            
                            {/* Temporary Visualization for debugging: */}
                            <div style={{background: '#f8f9fa', padding: '15px', borderRadius: '8px', maxHeight: '300px', overflowY: 'auto'}}>
                                <p style={{fontWeight: 'bold', color: '#007bff'}}>Latest Prediction: {chartData[0]?.level.toFixed(3)} meters</p>
                                <table style={{width: '100%', fontSize: '0.85rem', textAlign: 'left'}}>
                                    <thead>
                                        <tr style={{borderBottom: '1px solid #ddd'}}>
                                            <th style={{padding: '5px'}}>Time</th>
                                            <th style={{padding: '5px'}}>Level (m)</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {chartData.map((row, i) => (
                                            <tr key={i} style={{borderBottom: '1px solid #eee'}}>
                                                <td style={{padding: '5px'}}>{row.time}</td>
                                                <td style={{padding: '5px'}}>{row.level.toFixed(3)}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                            {/* ---------------------------------------------------- */}
                        </div>
                    ) : (
                        <div style={{padding: '40px', textAlign: 'center', color: '#999'}}>
                            Waiting for data...
                        </div>
                    )}
                </div>

                {/* 2. LIME EXPLANATIONS CARD */}
                <div className="lime-card">
                    <h2>AI Explanations</h2>
                    <div className="lime-list">
                        {limeSentences.map((line, index) => {
                             // Logic to detect positive/negative sentiment for icons
                             const isIncrease = line.toLowerCase().includes('increase') || line.includes('+');
                             const isDecrease = line.toLowerCase().includes('decrease') || line.includes('-');
                             
                             // Clean up the text if needed (remove old tags if they exist in file)
                             const cleanLine = line.replace(/\[GREEN\]|\[ORANGE\]/gi, '').trim();
                             
                             let icon = 'ℹ️';
                             if (isIncrease) icon = '📈'; // Trend Up
                             if (isDecrease) icon = '📉'; // Trend Down

                             return (
                                 <div key={index} className="lime-item">
                                     <div className="lime-icon">{icon}</div>
                                     <div style={{fontWeight: 500, fontSize: '0.9rem'}}>{cleanLine}</div>
                                 </div>
                             )
                        })}
                        {limeSentences.length === 0 && !loading && (
                            <p style={{padding: '20px', color: '#999', textAlign: 'center'}}>No explanations available.</p>
                        )}
                    </div>
                </div>

                {/* 3. DISCLAIMER */}
                <div style={{ marginTop: '30px', background: 'white', borderRadius: '15px', padding: '25px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
                    <div style={{ padding: '15px', background: '#fff3cd', borderRadius: '10px', color: '#856404', textAlign: 'center', fontSize: '0.9em' }}>
                        <strong>DISCLAIMER:</strong> This system provides general flood risk information. 
                        In emergency, call 100 (Police) or 101 (Fire & Rescue).
                    </div>
                </div>

            </div>

            {/* FLOATING REFRESH BUTTON */}
            <button className="refresh-btn" onClick={fetchData} title="Refresh Data">
                🔄
            </button>
        </div>
    );
};

export default RiverDashboard;
